import {arenas,setArena,getArena} from './arenas.js';
const streets=document.body.dataset.game==='streets'||location.pathname.endsWith('streets.html');
if(streets)setArena('streets');
const choices=streets?[{id:'streets',name:'7 BAIRROS · 5 REGIÕES',image:'assets/neighborhoods/jorge-teixeira.png'},...arenas.filter(a=>a.id!=='band')]:arenas;
const section=document.createElement('section');section.className='arena-selector';section.setAttribute('aria-label','Seleção de cenário');section.innerHTML=`<div class="arena-select-title"><div><p class="eyebrow">ESCOLHA ONDE A DISCUSSÃO ESQUENTA</p><h2>${streets?'RUAS OU ARENAS.':'UM PAÍS DE CENÁRIOS.'}</h2></div><span>${streets?'ESCOLHA PARA A PRÓXIMA PARTIDA':'5 ARENAS · 16 LUTADORES'}</span></div><div class="arena-options">${choices.map(a=>`<button data-arena="${a.id}" aria-pressed="${getArena()===a.id}" class="${getArena()===a.id?'active':''}"><img src="${a.image}" alt="${a.name}" loading="lazy"><span>${a.name}</span></button>`).join('')}</div><p class="arena-source-note">${streets?'Sete cenários de bairros reais e missões extras. Figurinos e confrontos são interpretações artísticas.':'Cenários fictícios reconstruídos a partir de fotografias. As instituições e pessoas de fundo não participam do combate.'}</p>`;
document.querySelector('.selection').before(section);
for(const b of section.querySelectorAll('[data-arena]'))b.onclick=()=>{setArena(b.dataset.arena);for(const e of section.querySelectorAll('[data-arena]')){e.classList.toggle('active',e===b);e.setAttribute('aria-pressed',e===b)}const a=arenas.find(a=>a.id===b.dataset.arena);if(!streets){const label=document.querySelector('.arena-top>span>b');if(label)label.textContent=a.name;const footer=document.querySelector('.arena-bottom>span');if(footer)footer.textContent=a.place+' · CENÁRIO RECONSTRUÍDO / FICÇÃO'}window.dispatchEvent(new CustomEvent('brasa-arena',{detail:b.dataset.arena}))};
